fam.compteurs.moyenne-positifs.01.referenceSolution:
int s = 0;
int cpt = 0;
for (int j = 0; j < valeurs.length; j++) {
    if (valeurs[j] > 0) {
        s += valeurs[j];
        cpt++;
    }
}
double moy = 0.0;
if (cpt > 0) {
    moy = (double) s / cpt;
}

