fam.compteurs.plus-longue-serie.01.referenceSolution:
int maxSerie = 0;
int courant = 0;
for (int j = 0; j < valeurs.length; j++) {
    if (j > 0 && valeurs[j] == valeurs[j - 1]) {
        courant++;
    } else {
        courant = 1;
    }
    if (courant > maxSerie) {
        maxSerie = courant;
    }
}

